import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.CFuv5BrO.js";const h=JSON.parse('{"title":"Phased Product Roadmap","description":"Hearth Stage 0–6 product roadmap: stage goals, scope, exit criteria, learning objectives, and explicit deferrals.","frontmatter":{"title":"Phased Product Roadmap","description":"Hearth Stage 0–6 product roadmap: stage goals, scope, exit criteria, learning objectives, and explicit deferrals.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/roadmap.md","filePath":"en/delivery/roadmap.md","lastUpdated":1793706118000}'),r={name:"en/delivery/roadmap.md"};function l(n,e,s,d,c,p){return a(),i("div",null,[...e[0]||(e[0]=[o('<p class="eyebrow">PRODUCT ROADMAP</p><h1 id="phased-product-roadmap" tabindex="-1">Phased Product Roadmap <a class="header-anchor" href="#phased-product-roadmap" aria-label="Permalink to &quot;Phased Product Roadmap&quot;">​</a></h1><p class="lead">Capability gates for Stage 0–6: what each stage delivers, when it counts as complete, and which unmet conditions block entry into the next stage.</p><h2 id="how-to-read-this-document" tabindex="-1">How to Read This Document <a class="header-anchor" href="#how-to-read-this-document" aria-label="Permalink to &quot;How to Read This Document&quot;">​</a></h2><ul><li>Stage is a capability level, not a date or schedule.</li><li>The MVP is an early exit from Stage 1, not a product of Stage 6.</li><li>Every stage must simultaneously have a user-visible interface, persistent state, verification evidence, and a recovery path.</li><li>A stage is complete only when all exit conditions are met; you can stay, trial, and roll back, but cannot skip steps.</li></ul><hr><h2 id="phased-product-roadmap-from-prototype-to-personal-agent-os" tabindex="-1">Phased Product Roadmap: From Prototype to Personal Agent OS <a class="header-anchor" href="#phased-product-roadmap-from-prototype-to-personal-agent-os" aria-label="Permalink to &quot;Phased Product Roadmap: From Prototype to Personal Agent OS&quot;">​</a></h2><h3 id="guiding-principles" tabindex="-1">Guiding Principles <a class="header-anchor" href="#guiding-principles" aria-label="Permalink to &quot;Guiding Principles&quot;">​</a></h3><ul><li>Advance by capability gates, not by calendar commitments;</li><li>Each stage can deliver value independently;</li><li>Within Stage 1, a daily-usable MVP must appear as early as possible, rather than waiting until Stage 6 for a product to take shape;</li><li>Every stage must deliver, at the same time, a user-visible interface, persistent state, verification evidence, and a recovery path;</li><li>Frontend and backend progress together in vertical slices; “finish the backend first, then add the interface” is not allowed;</li><li>Prove reliability before expanding coverage;</li><li>Codex is the first external Executor, but not the only source of capability;</li><li>Do not build a general-purpose Sandbox, model inference engine, or full Agent framework in-house early on;</li><li>Every stage has both product gates and learning gates;</li><li>Before any automation capability can produce real side effects, it must first pass safety and recovery tests.</li></ul><h3 id="stage-overview" tabindex="-1">Stage Overview <a class="header-anchor" href="#stage-overview" aria-label="Permalink to &quot;Stage Overview&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Stage</th><th>Product Form Delivered to Users</th><th>Core Capabilities</th><th>Explicitly Out of Scope</th><th>Main Risks</th></tr></thead><tbody><tr><td>Stage 0</td><td>Clickable end-to-end product prototype</td><td>Product wedge, task set, protocols, interactions, evaluation, and security baseline</td><td>Real execution, real side effects</td><td>Goal drift, prototype and implementation diverging</td></tr><tr><td>Stage 1</td><td>Locally usable personal task workbench; MVP appears early</td><td>Recoverable kernel, Codex, Web task cards, approvals, artifacts, recovery</td><td>Real automated email sending, GUI, proactive loops, multi-device</td><td>State recovery, duplicate side effects, integration instability</td></tr><tr><td>Stage 2</td><td>Personal Operator capable of handling daily content work</td><td>Real tasks across email/calendar/documents/web/data, Context Compiler, Memory v0</td><td>Desktop GUI, full proactivity, self-evolution</td><td>Permissions, platform limits, context cost</td></tr><tr><td>Stage 3</td><td>Computer Operator capable of operating the desktop</td><td>agentd, GUI, takeover, desktop isolation, and high-risk approvals</td><td>Long-term multi-device sync, unevaluated evolution</td><td>Fragility, verification, irreversible operations</td></tr><tr><td>Stage 4</td><td>Low-interruption Proactive Personal Agent</td><td>Trigger, proactive loops, attention budget, mobile PWA, device pairing</td><td>Full multi-device execution, automatic skill promotion</td><td>Notification fatigue, privilege escalation, mobile security</td></tr><tr><td>Stage 5</td><td>Agent that accumulates personal context and safely improves its methods</td><td>Memory OS, Evolution OS, skill evaluation/promotion/rollback</td><td>Enterprise multi-tenancy, public marketplace</td><td>Memory contamination, skill drift, evaluation bias</td></tr><tr><td>Stage 6</td><td>Multi-device, portable, long-running Personal Agent OS v1.0</td><td>Sync, offline queues, device revocation, backup migration, long-term operations</td><td>Unbounded unattended high-risk automation</td><td>Sync conflicts, device security, operations</td></tr></tbody></table><p>Stages are not a date-driven waterfall but a set of capability dependencies. You can stay, trial, and roll back at each stage; at any stage, the product should remain fully usable within its current scope.</p><p><strong>Where the MVP Sits:</strong> The MVP is an early product exit from Stage 1, positioned before the full Stage 1 gate. It does not include email, calendar, GUI, proactivity, full memory, or multi-device support, but it must include real execution, persistent Task state, Web task cards, Artifacts, approval drills, and failure recovery. See 25.3 for the specific definition.</p><h3 id="stage-0-definition-prototype-and-baseline" tabindex="-1">Stage 0: Definition, Prototype, and Baseline <a class="header-anchor" href="#stage-0-definition-prototype-and-baseline" aria-label="Permalink to &quot;Stage 0: Definition, Prototype, and Baseline&quot;">​</a></h3><p>Development module: <a href="/hearth-os/en/delivery/stage-0.html">Stage 0 · Definition &amp; Prototype</a></p><p><strong>Goal:</strong> Before entering real implementation, pin down the product, interactions, protocols, and acceptance criteria. Stage 0 is not a pure documentation phase; it must produce a clickable end-to-end product prototype.</p><p>Deliverables:</p><ul><li>A one-page product definition and non-goals;</li><li>Target users and a list of 20–30 real tasks;</li><li>A coverage matrix for eight task categories;</li><li>The first product wedge: prioritize one high-frequency, low-external-risk task family for the MVP;</li><li>A clickable Web prototype: Today, task cards, new task, Needs You, artifacts, failure/recovery, and approval states;</li><li>The projection fields and primary actions corresponding to each UI state;</li><li>schema v0 for Event, Task, Run, Executor, Approval, and Receipt;</li><li>Threat model and risk classification;</li><li>Evaluation task set and validator v0;</li><li>Build vs Integrate ADR;</li><li>Repository, CI, coding standards, and versioning strategy.</li></ul><p>Exit criteria:</p><ul><li>Can explain in one sentence what Hearth is not;</li><li>Every core entity has invariants;</li><li>At least 12 tasks have executable acceptance criteria;</li><li>High-risk actions have a clear approval path;</li><li>In the prototype, users can complete the sequence “create Task → see status → approve → view Artifact → view recovery path”;</li><li>Every state in the prototype maps to a real data contract, not just an animation for demonstration;</li><li>It has been decided that Stage 1 will not build a Sandbox kernel in-house.</li></ul><h3 id="stage-1-durable-personal-kernel-and-mvp" tabindex="-1">Stage 1: Durable Personal Kernel and MVP <a class="header-anchor" href="#stage-1-durable-personal-kernel-and-mvp" aria-label="Permalink to &quot;Stage 1: Durable Personal Kernel and MVP&quot;">​</a></h3><p>Development module: <a href="/hearth-os/en/delivery/stage-1.html">Stage 1 · Durable Kernel &amp; MVP</a></p><p><strong>Goal:</strong> Prove that a personal Agent can complete real tasks while running locally as a persistent service and remaining interruptible, recoverable, approvable, and auditable, and that a minimum daily-usable product can take shape as early as possible.</p><p><strong>MVP Completion Threshold:</strong> Stage 1 does not wait for all kernel details to be finished before showing a product. First complete a real vertical slice in one narrow task family to meet the MVP gate in 25.3; then continue filling in side-effect safety, a second task family, and fault injection to complete all of Stage 1.</p><p>Scope:</p><ul><li><code>hearthd</code> single-process persistent service;</li><li>SQLite WAL Event Log, projections, and migration;</li><li>Task / Ticket / Run / Assignment / Lease;</li><li>outbox, idempotency keys, Receipt;</li><li>Codex Executor: code, tests, Issue/PR, research, documentation, and multi-file workspaces;</li><li>workspace lifecycle, read-only evidence, file diff;</li><li>Policy, Mandate, Approval v0;</li><li>Web as the primary entry point: task creation, task cards, details/timeline, approvals, artifacts, failure and recovery;</li><li>CLI as an automation and diagnostics entry point, not a replacement for the product interface; mobile PWA is deferred to Stage 4;</li><li>Artifact and validator v0;</li><li>Basic Token logging and budgeting;</li><li>Crash recovery and fault injection tests.</li></ul><p>First batch of real tasks:</p><ol><li>From Issue to code changes, tests, and PR drafts;</li><li>Organize three source materials into a comparison table and report;</li><li>Read a set of documents and generate a weekly report draft and citation list;</li><li>File organization and reproducible transformations;</li><li>External side effects that require approval (using a test Effect or a local test service).</li></ol><p>Exit criteria:</p><ul><li>The MVP can be used daily in a browser for one narrow task family;</li><li>After <code>kill -9</code>, it can recover to a continuable state;</li><li>Zero duplicate external side effects under 200 fault injections;</li><li>Codex tasks have structured artifacts and verification;</li><li>No task is “completed” based solely on natural language;</li><li>Task cards clearly show status, artifacts, and next steps;</li><li>Creation, cancellation, retry, approval, artifact viewing, and recovery can all be completed through the Web;</li><li>At least 10 real tasks pass manual acceptance;</li><li>There is a baseline for Tokens and human minutes.</li></ul><p>Learning gates:</p><ul><li>Understand the Event Log, single writer, lease, fencing token, and recovery;</li><li>Understand Codex&#39;s capability boundaries and workspace isolation;</li><li>Understand the differences between Approval, outbox, and Receipt;</li><li>Produce the first failure classification and routing data.</li></ul><h3 id="stage-2-personal-operator" tabindex="-1">Stage 2: Personal Operator <a class="header-anchor" href="#stage-2-personal-operator" aria-label="Permalink to &quot;Stage 2: Personal Operator&quot;">​</a></h3><p>Development module: <a href="/hearth-os/en/delivery/stage-2.html">Stage 2 · Personal Operator</a></p><p><strong>Goal:</strong> Expand from “can do file tasks” to “can do most everyday digital content work.”</p><p>Scope:</p><ul><li>Email Connector: read-only sync, threads, contacts, attachments, drafts, send pending approval;</li><li>Calendar Connector: read-only, conflict checking, writes pending approval;</li><li>Docs/Drive Connector: read, versions, export, sharing pending approval;</li><li>Browser Executor: research, downloads, forms without APIs;</li><li>Document/Data Executor: PDF, Office, spreadsheets, OCR, conversion, reconciliation;</li><li>Context Compiler and Token Governor v1;</li><li>Memory v0: Episodic + Semantic, with provenance, budgets, and basic forgetting;</li><li>Task templates and the first batch of reusable workflows;</li><li>More complete notifications and Artifact center.</li></ul><p>Exit criteria:</p><ul><li>The email &quot;read—understand—draft—approve—send—receipt&quot; loop is usable;</li><li>Calendar conflict checking and writes pending approval are usable;</li><li>Document conversion results are verifiable;</li><li>Web research has sources and citations;</li><li>Manual minutes for common tasks drop significantly;</li><li>No cross-account or cross-project data crosstalk;</li><li>On failure, the system can recover or explicitly hand off to a human.</li></ul><h3 id="stage-3-computer-operator" tabindex="-1">Stage 3: Computer Operator <a class="header-anchor" href="#stage-3-computer-operator" aria-label="Permalink to &quot;Stage 3: Computer Operator&quot;">​</a></h3><p>Development module: <a href="/hearth-os/en/delivery/stage-3.html">Stage 3 · Computer Operator</a></p><p><strong>Goal:</strong> Cover desktop software without APIs and cross-application workflows.</p><p>Scope:</p><ul><li>Device agentd and desktop capability registration;</li><li>GUI Executor: accessibility tree, screenshots, keyboard and mouse, file selection;</li><li>Isolated virtual desktop;</li><li>Real-time browser/desktop takeover;</li><li>Approval for high-risk desktop actions;</li><li>Desktop task verification and recovery;</li><li>Application allowlists, window scopes, and system security boundaries.</li></ul><p>Exit criteria:</p><ul><li>At least 5 real desktop tasks can be completed and verified;</li><li>The takeover flow is usable, and users can pause, operate, and hand back control;</li><li>GUI failures do not leave half-completed high-risk states;</li><li>Desktop operations do not read password vaults or exceed system settings permissions;</li><li>Tokens and manual minutes are within acceptable ranges.</li></ul><h3 id="stage-4-proactive-personal-agent" tabindex="-1">Stage 4: Proactive Personal Agent <a class="header-anchor" href="#stage-4-proactive-personal-agent" aria-label="Permalink to &quot;Stage 4: Proactive Personal Agent&quot;">​</a></h3><p>Development module: <a href="/hearth-os/en/delivery/stage-4.html">Stage 4 · Proactive Personal Agent</a></p><p><strong>Goal:</strong> Enable Hearth to work proactively within limited authorization while keeping interruptions low.</p><p>Scope:</p><ul><li>Triggers for email, calendar, files, web, and task dependencies;</li><li>Proactive loops and background batch processing;</li><li>Attention budgets, quiet hours, aggregated notifications;</li><li>Mobile PWA: view, approve, take over, initiate, notify;</li><li>Device pairing, secure tunnels, push notification redaction;</li><li>A1/A2 autonomy levels;</li><li>Mature Task cards and a &quot;Needs You&quot; inbox;</li><li>Toggles for proactive mode and controlled evaluation.</li></ul><p>Exit criteria:</p><ul><li>Proactive tasks are genuinely useful and do not create notification fatigue;</li><li>Interruptions per Task ≤ 1;</li><li>High-risk actions still require approval;</li><li>Mobile can complete key approvals and takeovers;</li><li>Users can pause, revoke, and downgrade proactive mode at any time;</li><li>No unbounded background loops or budget overruns.</li></ul><h3 id="stage-5-memory-os-and-evolution-os" tabindex="-1">Stage 5: Memory OS and Evolution OS <a class="header-anchor" href="#stage-5-memory-os-and-evolution-os" aria-label="Permalink to &quot;Stage 5: Memory OS and Evolution OS&quot;">​</a></h3><p>Development module: <a href="/hearth-os/en/delivery/stage-5.html">Stage 5 · Memory &amp; Evolution</a></p><p><strong>Goal:</strong> Enable the system to truly accumulate personal context and safely improve its methods.</p><p>Scope:</p><ul><li>Full implementation of the five memory types;</li><li>Memory writes, conflicts, retrieval, budgets, forgetting, sync;</li><li>Memory browser and a &quot;why was this recalled&quot; view;</li><li>Trajectory mining, skill candidates, versions, and evaluation sets;</li><li>Shadow → Canary → Promote → Rollback;</li><li>Skill permission constraints;</li><li>Manual PR changes to the core Runtime;</li><li>At least one complete skill promotion case.</li></ul><p>Exit criteria:</p><ul><li>Memory can be corrected, forgotten, and exported;</li><li>Memory injection accuracy meets the target;</li><li>Skill promotion has controlled evaluation;</li><li>No permission expansion or security regression;</li><li>Rollback is usable;</li><li>Users can understand why the system did what it did.</li></ul><h3 id="stage-6-personal-agent-os" tabindex="-1">Stage 6: Personal Agent OS <a class="header-anchor" href="#stage-6-personal-agent-os" aria-label="Permalink to &quot;Stage 6: Personal Agent OS&quot;">​</a></h3><p>Development module: <a href="/hearth-os/en/delivery/stage-6.html">Stage 6 · Multi-device &amp; Operations</a></p><p><strong>Goal:</strong> Multi-device, long-running, migratable, and self-hostable.</p><p>Scope:</p><ul><li>Multi-device agentd;</li><li>Event sync, cursor, lease, fencing;</li><li>Device capability routing and offline queues;</li><li>Device loss revocation;</li><li>Remote execution and encrypted transport;</li><li>Backup, restore, migration, and upgrade;</li><li>Long-running monitoring;</li><li>Resource scheduling and quotas;</li><li>Optional remote Sandbox.</li></ul><p>Exit criteria:</p><ul><li>One logical Agent, consistent across multiple devices;</li><li>Device switching does not lose Tasks or duplicate side effects;</li><li>Offline recovery rate meets the target;</li><li>After migration, events, memory, and skills are verifiable;</li><li>Device revocation is immediately reliable;</li><li>Long-running operation has no memory leaks or state drift.</li></ul><h3 id="learning-goal-mapping" tabindex="-1">Learning Goal Mapping <a class="header-anchor" href="#learning-goal-mapping" aria-label="Permalink to &quot;Learning Goal Mapping&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Learning Goal</th><th>Primary Focus</th><th>Stage</th><th>Verifiable Deliverable</th></tr></thead><tbody><tr><td>Maka / Pi Runtime</td><td>Native Runtime, session tree, steering, compaction</td><td>1–2</td><td>Replayable session and context compaction tests</td></tr><tr><td>DeerFlow complete Harness</td><td>Ticket/Run, state machine, middleware, recovery</td><td>1</td><td>Run lifecycle and fault injection</td></tr><tr><td>OpenSandbox / OpenBot isolation</td><td>Execution Gateway, Sandbox Provider, takeover, receipt</td><td>1–3</td><td>Attack matrix and takeover demo</td></tr><tr><td>OpenClaw autonomous control</td><td>Gateway, channels, devices, attention, autonomy</td><td>2–4</td><td>Source→Trigger→Run→Receipt loop</td></tr><tr><td>Hermes memory and evolution</td><td>Memory budgets, constraints, skill lifecycle, evaluation</td><td>5</td><td>Memory evaluation and skill promotion/rollback cases</td></tr><tr><td>OpenMuse / OpenDots autonomy</td><td>Durable job, checkpoint, low-interruption Task cards</td><td>1–4</td><td>Crash recovery and mobile Task card demo</td></tr><tr><td>Codex Executor</td><td>Long chains, multi-file, research, documents, code</td><td>1</td><td>Task packages, structured output, and acceptance reports</td></tr></tbody></table><h3 id="explicitly-deferred" tabindex="-1">Explicitly Deferred <a class="header-anchor" href="#explicitly-deferred" aria-label="Permalink to &quot;Explicitly Deferred&quot;">​</a></h3><p>The Stage 0–1 MVP does not do:</p><ul><li>Build proprietary containers/VMs/kernels;</li><li>Build proprietary foundation models or inference engines;</li><li>Build a public Agent marketplace;</li><li>Enterprise IAM, multi-tenancy, billing;</li><li>A full desktop Office replacement;</li><li>Unbounded automatic payments, contracting, and public publishing;</li><li>Integrate all channels from the start;</li><li>Self-evolution without evaluation;</li><li>Complex multi-device sync;</li><li>Native iOS/Android apps;</li><li>A &quot;fake MVP&quot; with only a CLI or API and no browser product path;</li><li>Defer the entire frontend to later stages in order to rush underlying progress.</li></ul>',72)])])}const g=t(r,[["render",l]]);export{h as __pageData,g as default};
